  "Assist watches only what you type and what the session prints back. Command history for suggestions stays in memory and is never written to disk. No probe commands are ever sent to your servers.": {
    "en": "Assist watches only what you type and what the session prints back. Command history for suggestions stays in memory and is never written to disk. No probe commands are ever sent to your servers.",
    "de": "Assist überwacht nur das, was Sie eingeben und was die Sitzung zurückgibt. Der Befehlsverlauf für Vorschläge bleibt im Speicher und wird nie auf die Festplatte geschrieben. Es werden keine Sondierungsbefehle an Ihre Server gesendet.",
    "es": "Ayuda relojes sólo lo que escribe y lo que la sesión se imprime de nuevo. Historia del comando para sugerencias se queda en memoria y nunca se escribe en el disco. No se envían comandos de sonda a sus servidores.",
    "fr": "L'historique des commandes pour les suggestions reste en mémoire et n'est jamais écrit sur le disque. Aucune commande de sonde n'est jamais envoyée à vos serveurs.",
    "it": "La cronologia dei comandi per i suggerimenti rimane in memoria e non è mai scritta su disco. Nessun comando di sonda viene mai inviato ai tuoi server.",
    "ja": "どの種類のセッションが印刷されるかだけを監視します。 提案のコマンド履歴はメモリにとどまり、ディスクに書き込まれることはありません。 プローブコマンドは、サーバーに送信されることはありません。",
    "pt": "Assistir observa apenas o que você digita e o que a sessão imprime de volta. Histórico de comandos para sugestões permanece na memória e nunca é escrito para o disco. Nenhum comando sonda nunca são enviados para seus servidores.",
    "ru": "Ассист наблюдает только за тем, что вы вводите и что сеанс печатает обратно. История команд для предложений остается в памяти и никогда не записывается на диск. Никакие команды зонда никогда не отправляются на ваши серверы.",
    "zh": "协助只监视您输入的和会话打印的。 命令建议的历史会留在内存中, 并且永远不会被写入磁盘。 任何探测命令都不会被发送到您的服务器 。"
  },
  "Attach the last lines of session output as context": {
    "en": "Attach the last lines of session output as context",
    "de": "Fügen Sie die letzten Zeilen der Sitzungsausgabe als Kontext hinzu",
    "es": "Adjuntar las últimas líneas de producción del período de sesiones como contexto",
    "fr": "Joindre les dernières lignes de sortie de session en tant que contexte",
    "it": "Attaccare le ultime linee di output di sessione come contesto",
    "ja": "セッション出力の最後の行をコンテキストとしてアタッチ",
    "pt": "Anexar as últimas linhas de saída da sessão como contexto",
    "ru": "Приложить последние строки итогового документа сессии в качестве контекста",
    "zh": "附加会话输出的最后一行为上下文"
  },
  "Aux Command": {
    "en": "Aux Command",
    "de": "Aux Command",
    "es": "Aux Command",
    "fr": "Aux Command",
    "it": "Aux CommandX",
    "ja": "Aux Commandの特長",
    "pt": "Aux Command",
    "ru": "Aux CommandX",
    "zh": "Aux Command"
  },
  "Aux Command bundles local PTY, graphical SFTP, Telnet and serial bridges. RDP, VNC and Mosh still depend on host-installed clients/servers; X11 forwarding uses OpenSSH -X and the host display.": {
    "en": "Aux Command bundles local PTY, graphical SFTP, Telnet and serial bridges. RDP, VNC and Mosh still depend on host-installed clients/servers; X11 forwarding uses OpenSSH -X and the host display.",
    "de": "Aux Command bündelt lokale PTY, grafische SFTP, Telnet und serielle Brücken. RDP, VNC und Mosh sind immer noch von hostinstallierten Clients/servers abhängig; X11 Forwarding verwendet OpenSSH -X und das Host-Display.",
    "es": "Los paquetes Aux Command locales PTY, gráficos SFTP, Telnet y puentes serie. RDP, VNC y Mosh todavía dependen de los clientes instalados en el host/servers; X11 utiliza OpenSSH y la pantalla de host.",
    "fr": "Aux Command regroupe les ponts locaux PTY, les ponts graphiques SFTP, Telnet et série. RDP, VNC et Mosh dépendent toujours des clients installés par l'hôte/servers; la transmission X11 utilise OpenSSH -X et l'écran hôte.",
    "it": "Aux Command fasci locali PTY, grafica SFTP, Telnet e ponti seriali. RDP, VNC e Mosh dipendono ancora dai client installati in host /servers; X11 utilizza l'inoltro OpenSSH -X e il display host.",
    "ja": "Aux Command ローカルを束ねる PTY、グラフィカル SFTP、Telnetおよびシリアル橋。 RDP, , VNC そして、 Mosh ホストインストールされたクライアントに依存します。/servers;;; X11 転送用途 OpenSSH -X およびホストの表示。",
    "pt": "Aux Command empacota PTY local, SFTP gráfico, Telnet e pontes seriais. RDP, VNC e Mosh ainda dependem de clientes instalados no host/servers; X11 reencaminhamento usa OpenSSH -X e a exibição do host.",
    "ru": "Aux Command объединяет локальные PTY, графические SFTP, Telnet и последовательные мосты. RDP, VNC и Mosh по-прежнему зависят от хост-установленных клиентов /servers; форвардинг X11 использует OpenSSH-X и хост-дисплей.",
    "zh": "Aux Command捆绑了本地PTY,图形SFTP,Telnet和串行桥. RDP,VNC和Mosh仍然依赖于主机安装的客户端/servers;X11转发使用OpenSSH-X和主机显示."
  },
