  "Bring your own endpoint: nothing is ever sent to any AI service unless you ask, and only to the endpoint you configure here. Replies are inserted, never executed.": {
    "en": "Bring your own endpoint: nothing is ever sent to any AI service unless you ask, and only to the endpoint you configure here. Replies are inserted, never executed.",
    "de": "Bringen Sie Ihren eigenen Endpunkt mit: Nichts wird jemals an einen KI-Dienst gesendet, es sei denn, Sie fragen, und nur an den Endpunkt, den Sie hier konfigurieren. Antworten werden eingefügt, niemals ausgeführt.",
    "es": "Traiga su propio punto final: nunca se envía nada a ningún servicio AI a menos que pregunte, y sólo al punto final que configura aquí. Las respuestas se insertan, nunca se ejecutan.",
    "fr": "Apportez votre propre paramètre : rien n'est jamais envoyé à un service AI à moins que vous le demandiez, et seulement au paramètre que vous configurez ici. Les réponses sont insérées, jamais exécutées.",
    "it": "Porta il tuo endpoint: nulla viene mai inviato a qualsiasi servizio AI a meno che non lo chieda, e solo al punto finale che si configura qui. Le risposte sono inserite, mai eseguite.",
    "ja": "自分のエンドポイントを持たせてください:あなたが尋ねる限り、AIサービスに送られるものは何もありません。ここで設定するエンドポイントだけ。 返信は、決して実行されません。",
    "pt": "Traga seu próprio endpoint: nada é enviado para qualquer serviço de IA a menos que você pergunte, e apenas para o endpoint que você configurar aqui. Respostas são inseridas, nunca executadas.",
    "ru": "Принесите свою собственную конечную точку: ничто никогда не отправляется на какую-либо услугу ИИ, если вы не попросите, и только на конечную точку, которую вы настраиваете здесь.",
    "zh": "带出你自己的终点: 除非您询问, 任何AI 服务都不会被发送到任何端点, 只有您在此配置的端点。 答复被插入, 从未执行 。"
  },
