  "Color keywords in terminal output to speed up log triage. Rules apply to every terminal and persist across restarts.": {
    "en": "Color keywords in terminal output to speed up log triage. Rules apply to every terminal and persist across restarts.",
    "de": "Farbschlüsselwörter in der terminalausgabe, um die protokoll-triage zu beschleunigen regeln gelten für jedes terminal und bleiben bei neustarts bestehen.",
    "es": "Palabras clave de color en la salida de la terminal para acelerar el triaje de registro. Las reglas se aplican a cada terminal y persisten en los reinicios.",
    "fr": "Mots-clés de couleur dans la sortie du terminal pour accélérer le triage du journal. Les règles s'appliquent à chaque terminal et persistent sur les redémarrages.",
    "it": "Parole chiave di colore in uscita terminale per velocizzare il triage di log. Le regole si applicano ad ogni terminale e persistono attraverso riavviamento.",
    "ja": "ターミナル出力の色のキーワードは、ログトリアージを高速化します。 ルールは、すべての端末とリスタート時に永続的に適用されます。",
    "pt": "Palavras- chave coloridas na saída do terminal para acelerar a triagem do log. As regras aplicam- se a cada terminal e persistem ao longo das reiniciagens.",
    "ru": "Цвет ключевых слов в выводе терминала для ускорения сортировки журналов. Правила применяются к каждому терминалу и сохраняются при перезапуске.",
    "zh": "终端输出中的彩色关键字以加快日志分解。规则适用于每个终端,并贯穿重启。"
  },
