  "Inline editing is limited to UTF-8 text files up to 1 MB. Saving overwrites the remote file atomically via a temporary upload then rename.": {
    "en": "Inline editing is limited to UTF-8 text files up to 1 MB. Saving overwrites the remote file atomically via a temporary upload then rename.",
    "de": "Die Inline-Bearbeitung ist auf UTF-8-Textdateien bis zu 1 MB beschränkt. Das Speichern überschreibt die Remote-Datei atomar über einen temporären Upload und nennt sie dann um.",
    "es": "La edición en línea se limita a los archivos de texto UTF-8 hasta 1 MB. Ahorrando sobrescribe el archivo remoto atómico a través de una carga temporal y luego renombrar.",
    "fr": "L'édition en ligne est limitée aux fichiers texte UTF-8 jusqu'à 1 Mo. L'enregistrement écrase le fichier distant de façon atomique via un téléchargement temporaire puis renomme.",
    "it": "La modifica in linea è limitata ai file di testo UTF-8 fino a 1 MB. Risparmio sovrascrive il file remoto atomicamente tramite un upload temporaneo quindi rinomina.",
    "ja": "インライン編集は、UTF-8テキストファイル最大1 MBに制限されます。 保存は、一時的なアップロードを介して原子的にリモートファイルを上書きし、名前を変更します。",
    "pt": "Edição em linha é limitada a arquivos de texto UTF-8 até 1 MB. Salvar substitui o arquivo remoto atomicamente através de um upload temporário, em seguida, renomear.",
    "ru": "Встроенное редактирование ограничено текстовыми файлами UTF-8 объемом до 1 Мб. Сохранение перезаписывает удаленный файл атомарно через временную загрузку, а затем переименовывает.",
    "zh": "内置编辑仅限于 UTF-8 1 MB 的文本文件。 通过临时上传再重命名来解析远程文件 。"
  },
