  "Macro recording may capture secrets typed into this terminal. Do not record passwords, tokens, recovery codes, or private customer data.": {
    "en": "Macro recording may capture secrets typed into this terminal. Do not record passwords, tokens, recovery codes, or private customer data.",
    "de": "Makro-Aufzeichnungen können Geheimnisse erfassen, die in dieses Terminal eingegeben wurden, und keine Passwörter, Token, Wiederherstellungscodes oder private Kundendaten aufzeichnen.",
    "es": "La grabación de Macro puede capturar secretos escritos en esta terminal. No registre contraseñas, fichas, códigos de recuperación o datos de clientes privados.",
    "fr": "L'enregistrement macro peut capturer des secrets tapés dans ce terminal. N'enregistrez pas les mots de passe, les jetons, les codes de récupération ou les données personnelles du client.",
    "it": "Registrazione Macro può catturare segreti digitati in questo terminale. Non registrare password, gettoni, codici di recupero, o dati dei clienti privati.",
    "ja": "マクロ録画は、このターミナルに入力された秘密をキャプチャできます。パスワード、トークン、回復コード、またはプライベートな顧客データを記録しないでください。",
    "pt": "A gravação de macro pode capturar segredos digitados neste terminal. Não grave senhas, tokens, códigos de recuperação ou dados de clientes privados.",
    "ru": "Запись Macro может захватывать секреты, введённые в этот терминал. Не записывайте пароли, токены, коды восстановления или данные частных клиентов.",
    "zh": "宏记录可以捕捉输入此终端的秘密。 不要记录密码、 令牌、 恢复代码或私人客户数据 。"
  },
