  "Managed tunnels use OpenSSH BatchMode. Configure key or SSH-agent authentication; interactive password and MFA prompts are not available for background tunnels.": {
    "en": "Managed tunnels use OpenSSH BatchMode. Configure key or SSH-agent authentication; interactive password and MFA prompts are not available for background tunnels.",
    "de": "Verwaltete Tunnel verwenden OpenSSH BatchMode. Konfigurieren Sie den Schlüssel oder die SSH-Agent-Authentifizierung; interaktives Passwort und MFA-Eingabeaufforderungen sind für Hintergrundtunnel nicht verfügbar.",
    "es": "Los túneles administrados utilizan OpenSSH BatchMode. Configurar la autenticación clave o SSH-agent; contraseña interactiva y las indicaciones MFA no están disponibles para los túneles de fondo.",
    "fr": "Les tunnels gérés utilisent OpenSSH BatchMode. Configurez la clé ou l'authentification SSH-agent; les mots de passe interactifs et les instructions MFA ne sont pas disponibles pour les tunnels de fond.",
    "it": "Utilizzo di gallerie gestite OpenSSH BatchMode. Configurare la chiave o SSHautenticazione dell'agente; password interattiva e MFA le richieste non sono disponibili per i tunnel di fondo.",
    "ja": "管理されたトンネルは、OpenSSH BatchMode を使用します。キーまたは SSH-agent 認証の設定、インタラクティブなパスワードと MFA プロンプトは、バックグラウンドトンネルでは利用できません。",
    "pt": "Os túneis gerenciados usam OpenSSH BatchMode. Configure a chave ou a autenticação do agente SSH; senha interativa e prompts MFA não estão disponíveis para túneis de fundo.",
    "ru": "Управляемые туннели используют OpenSSH BatchMode. Настройка ключа или аутентификация SSH-агента; интерактивные пароли и подсказки MFA недоступны для фоновых туннелей.",
    "zh": "管理的地道使用OpenSSH BatchMode. 配置密钥或SSH-代理认证;背景地道没有交互密码和MFA 提示."
  },
