  "One or more bastion hops for the OpenSSH -J option, e.g. bastion or user@bastion:2222,inner. Applies to terminals, tunnels, and graphical SFTP.": {
    "en": "One or more bastion hops for the OpenSSH -J option, e.g. bastion or user@bastion:2222,inner. Applies to terminals, tunnels, and graphical SFTP.",
    "de": "Ein oder mehrere Bastion-Hops für die Option OpenSSH -J, z. B. bastion oder user@bastion:2222,inner. Gilt für Terminals, Tunnel und grafische SFTP.",
    "es": "Uno o más tubos bastion para la opción OpenSSH -J, por ejemplo bastion o user@bastion:2222,inner. Aplica a terminales, túneles y SFTP gráfico.",
    "fr": "Un ou plusieurs bastion hop pour l'option OpenSSH -J, p.ex. bastion ou user@bastion:2222,inner. S'applique aux terminaux, tunnels et graphiques SFTP.",
    "it": "Uno o più bastioni per il OpenSSH -J opzione, ad esempio bastion o user@bastion:2222, interno. SFTP.",
    "ja": "OpenSSH -Jオプション、bastionまたはuser@bastion:2222、innerの1つ以上のbastionホップ。 ターミナル、トンネル、およびグラフィックSFTPに適用されます。",
    "pt": "Um ou mais bastiões para o OpenSSH - Opção J, por exemplo, bastião ou user@bastion:2222, inner. Aplica-se a terminais, túneis e gráficos SFTP.",
    "ru": "Один или несколько бастионных прыжков для опции OpenSSH-J, например, bastion или user@bastion:2222,inner.Применяется к терминалам, туннелям и графическому SFTP.",
    "zh": "OpenSSH-J选项的一个或多个bastion hops, 例如: bastion 或 user@bastion:2222. inner. 应用到终端,地道,和图形 SFTP."
  },
  "Only empty remote folders can be removed.": {
    "en": "Only empty remote folders can be removed.",
    "de": "Lediglich leere Fernordner können entfernt werden.",
    "es": "Sólo se pueden eliminar carpetas remotas vacías.",
    "fr": "Seuls les dossiers distants vides peuvent être supprimés.",
    "it": "Solo le cartelle remote vuote possono essere rimosse.",
    "ja": "リモートフォルダのみを削除できます。",
    "pt": "Só podem ser removidas pastas remotas vazias.",
    "ru": "Удалять можно только пустые удаленные папки.",
    "zh": "只可删除空远程文件夹 。"
  },
  "Only import files you trust: they may contain startup commands and snippets. Credentials are not imported; local credentials are retained only for an unchanged connection.": {
    "en": "Only import files you trust: they may contain startup commands and snippets. Credentials are not imported; local credentials are retained only for an unchanged connection.",
    "de": "Importieren Sie nur Dateien, denen Sie vertrauen: Sie können Startbefehle und Snippets enthalten. Anmeldeinformationen werden nicht importiert; lokale Anmeldeinformationen werden nur für eine unveränderte Verbindung beibehalten.",
    "es": "Importe solo archivos de confianza: pueden contener comandos de inicio y fragmentos. No se importan credenciales; las credenciales locales solo se conservan si la conexión no cambia.",
    "fr": "Importez uniquement des fichiers de confiance : ils peuvent contenir des commandes de démarrage et des extraits. Les identifiants ne sont pas importés ; les identifiants locaux sont conservés uniquement si la connexion reste inchangée.",
    "it": "Solo i file di importazione di cui ti fidi: possono contenere comandi di avvio e snippets. Le credenziali non sono importate; le credenziali locali sono conservate solo per una connessione invariata.",
    "ja": "信頼するファイルをインポートするだけで: 起動コマンドとスニペットが含まれている場合があります。 認証情報はインポートされません。 ローカルの認証情報は変更されていない接続のみ保持されます。",
    "pt": "Importe apenas ficheiros de confiança: podem conter comandos de arranque e excertos. As credenciais não são importadas; as credenciais locais só são mantidas se a ligação não mudar.",
    "ru": "Только импортные файлы, которым вы доверяете: они могут содержать команды запуска и фрагменты.Удостоверения не импортируются; локальные учетные данные сохраняются только для неизменного соединения.",
    "zh": "只导入您信任的文件：其中可能包含启动命令和代码片段。不会导入凭据；只有连接保持不变时，才会保留本地凭据。"
  },
