    "pt": "Ping, traceroute, DNS, varredura de porta, whois, e Wake-on-LAN.",
    "ru": "Ping, traceroute, DNS, сканирование портов, whois и Wake-on-LAN.",
    "zh": "平,微道,DNS,端口扫描,出站,和Wake-on-LAN."
