  "Plain FTP is not encrypted. Credentials and file contents can be observed on the network. Use FTPS unless this is a trusted legacy target.": {
    "en": "Plain FTP is not encrypted. Credentials and file contents can be observed on the network. Use FTPS unless this is a trusted legacy target.",
    "de": "Plain FTP ist nicht verschlüsselt. Anmeldeinformationen und Dateiinhalte können im Netzwerk beobachtet werden. Verwenden Sie FTPS, es sei denn, es handelt sich um ein vertrauenswürdiges Legacy-Ziel.",
    "es": "FTP sin cifrado expone las credenciales y el contenido de los archivos en la red. Utilice FTPS salvo para un sistema antiguo de confianza.",
    "fr": "FTP sans chiffrement expose les identifiants et le contenu des fichiers sur le réseau. Utilisez FTPS, sauf pour un ancien système de confiance.",
    "it": "Plain FTP non è crittografato. Credenziali e contenuti di file possono essere osservati sulla rete. Utilizzare FTPS a meno che questo non sia un obiettivo legacy affidabile.",
    "ja": "プレーンFTPは暗号化されていません。ネットワーク上での認証情報とファイルの内容が観察できます。信頼できるレガシーターゲットである場合を除き、FTPSを使用してください。",
    "pt": "O simples FTP não está criptografado. As credenciais e o conteúdo do arquivo podem ser observados na rede. Use o FTPS a menos que este seja um alvo legado confiável.",
    "ru": "Обычный FTP не зашифрован. В сети можно наблюдать учетные данные и содержимое файлов. Используйте FTPS, если это не доверенная унаследованная цель.",
    "zh": "普通FTP不加密。网络上的其他人可能看到凭据和文件内容。除非连接的是可信的旧系统，否则请使用FTPS。"
  },
  "Plain text matches literally; wrap a pattern in /slashes/ for a regular expression. Highlighting applies to normal terminal output, not full-screen apps like vim or htop.": {
    "en": "Plain text matches literally; wrap a pattern in /slashes/ for a regular expression. Highlighting applies to normal terminal output, not full-screen apps like vim or htop.",
    "de": "Klartext passt wörtlich; wickeln Sie ein Muster in /slashes/ für einen regulären Ausdruck ein. Hervorhebung gilt für den normalen Terminalausgang, nicht für Vollbild-Apps wie vim oder htop.",
    "es": "El texto de la línea coincide literalmente; envuelve un patrón en /slashes/ para una expresión regular. Destacar se aplica a la salida de la terminal normal, no aplicaciones de pantalla completa como vim o htop.",
    "fr": "Un texte simple correspond littéralement; envelopper un motif dans /slashes/ pour une expression régulière. L'en-tête s'applique à la sortie normale du terminal, pas aux applications plein écran comme vim ou htop.",
    "it": "Il testo normale corrisponde letteralmente; avvolgere un modello in /slashes/ per un'espressione regolare. L'illuminazione si applica alla normale uscita del terminale, non alle app a schermo intero come vim o htop.",
    "ja": "プレーンテキストは文字通りマッチします。通常の式では/slashes/でパターンをラップします。ハイライトは、vimやhtopなどのフルスクリーンアプリではなく、通常の端末出力に適用されます。",
    "pt": "O texto simples corresponde literalmente; embrulhe um padrão no /slashes/ para uma expressão regular. O realce aplica- se à saída normal do terminal, não a aplicações em ecrã completo como o vim ou o htop.",
    "ru": "Простой текст соответствует буквально; оберните шаблон в /slashes/ для регулярного выражения. Подсветка применяется к обычному выходу терминала, а не к полноэкранным приложениям, таким как vim или htop.",
    "zh": "纯文本字面匹配; 将一个图案用 /slashes/来包装正则表达式 。 突出显示适用于普通终端输出, 而不是像 vim 或 htop 这样的全屏幕应用 。"
  },
