  "Portable exports exclude saved passwords, private keys and SSH config files. Treat profile notes and commands as private data.": {
    "en": "Portable exports exclude saved passwords, private keys and SSH config files. Treat profile notes and commands as private data.",
    "de": "Portable Exporte enthalten keine gespeicherten Passwörter, privaten Schlüssel oder SSH-Konfigurationsdateien. Behandeln Sie Profilnotizen und Befehle als private Daten.",
    "es": "Las exportaciones portátiles excluyen contraseñas guardadas, claves privadas y archivos de configuración SSH. Trate notas de perfil y comandos como datos privados.",
    "fr": "Les exportations portatives excluent les mots de passe enregistrés, les clés privées et les fichiers de configuration SSH. Traitez les notes de profil et les commandes comme des données privées.",
    "it": "Le esportazioni portatili escludono password salvate, chiavi private e file di configurazione SSH. Considera le note dei profili e i comandi come dati privati.",
    "ja": "ポータブルエクスポートは、保存されたパスワード、プライベートキー、SSH設定ファイルを除外します。 プロファイルのメモとコマンドをプライベートデータとして扱います。",
    "pt": "Exportações portáteis excluem senhas salvas, chaves privadas e arquivos de configuração SSH. Trate notas de perfil e comandos como dados privados.",
    "ru": "Портативный экспорт исключает сохраненные пароли, приватные ключи и файлы конфигураций SSH. Относитесь к заметкам профиля и командам как к приватным данным.",
    "zh": "便携式出口不包括已保存的密码、私人密钥和 SSH 配置文件。 将配置说明和命令视为私有数据 。"
  },
