  "Select files or folders on either side, then review the transfer. Selected folders include their contents; symbolic links are not followed.": {
    "en": "Select files or folders on either side, then review the transfer. Selected folders include their contents; symbolic links are not followed.",
    "de": "Dateien oder Ordner auf einer Seite auswählen und die Übertragung prüfen. Ordnerinhalte werden einbezogen; symbolischen Links wird nicht gefolgt.",
    "es": "Selecciona archivos o carpetas en un lado y revisa la transferencia. Se incluye el contenido de las carpetas; no se siguen enlaces simbólicos.",
    "fr": "Sélectionnez des fichiers ou dossiers d’un côté, puis vérifiez le transfert. Le contenu des dossiers est inclus ; les liens symboliques ne sont pas suivis.",
    "it": "Seleziona file o cartelle su un lato, poi rivedi il trasferimento. Il contenuto delle cartelle è incluso; i collegamenti simbolici non vengono seguiti.",
    "ja": "いずれかの側でファイルやフォルダーを選択し、転送内容を確認してください。フォルダー内の項目も含まれます。シンボリックリンクはたどりません。",
    "pt": "Selecione ficheiros ou pastas num dos lados e reveja a transferência. O conteúdo das pastas é incluído; as ligações simbólicas não são seguidas.",
    "ru": "Выберите файлы или папки с любой стороны, затем проверьте передачу. Содержимое папок включается; символические ссылки не обходятся.",
    "zh": "在任意一侧选择文件或文件夹，然后审核传输。文件夹包含其内容；不会跟随符号链接。"
  },
