  "Terminal logs may capture secrets, commands, hostnames, customer data, and remote output. Choose the log file carefully and stop logging when finished.": {
    "en": "Terminal logs may capture secrets, commands, hostnames, customer data, and remote output. Choose the log file carefully and stop logging when finished.",
    "de": "Terminalprotokolle können Geheimnisse, Befehle, Hostnamen, Kundendaten und Fernausgabe erfassen. Wählen Sie die Protokolldatei sorgfältig aus und stoppen Sie die Protokollierung, wenn Sie fertig sind.",
    "es": "Los registros de la terminal pueden capturar secretos, comandos, nombres de host, datos del cliente y salida remota. Elija el archivo de registro cuidadosamente y deje de registrar cuando esté terminado.",
    "fr": "Les logs terminaux peuvent capturer des secrets, des commandes, des noms d'hôte, des données client et des sorties distantes.",
    "it": "I registri dei terminali possono catturare segreti, comandi, hostname, dati dei clienti e output remoto.",
    "ja": "ターミナルログは、秘密、コマンド、ホスト名、顧客データ、リモート出力をキャプチャできます。ログファイルを慎重に選択し、ログを終了したときにログを停止します。",
    "pt": "Os registros de terminais podem capturar segredos, comandos, nomes de máquinas, dados do cliente e saída remota. Escolha o arquivo de registro com cuidado e pare de registrar quando terminar.",
    "ru": "Терминальные журналы могут захватывать секреты, команды, имена хостов, данные о клиентах и удаленный вывод. Выбирайте лог-файл тщательно и прекратите регистрацию по завершении.",
    "zh": "终端日志可以捕捉机密,命令,主机名,客户数据,以及远程输出. 仔细选择日志文件,完成后停止日志."
  },
