  "Updates install only after the published manifest and updater metadata pass OpenPGP verification with the bundled Aux Command signing key.": {
    "en": "Updates install only after the published manifest and updater metadata pass OpenPGP verification with the bundled Aux Command signing key.",
    "de": "Updates werden erst installiert, nachdem die veröffentlichten Manifest- und Updater-Metadaten die OpenPGP-Verifizierung mit dem gebündelten Aux Command-Signierungsschlüssel bestanden haben.",
    "es": "Las actualizaciones se instalan sólo después de la publicación de metadatos de manifiesto y actualización pasan verificación OpenPGP con la clave de firma de Aux Command.",
    "fr": "Les mises à jour ne s'installent qu'après que les métadonnées de manifeste et de mise à jour publiées passent la vérification OpenPGP avec la clé de signature Aux Command.",
    "it": "Gli aggiornamenti si installano solo dopo il manifesto e l'aggiornamento dei metadati passano la verifica OpenPGP con la chiave di firma Aux Command in bundle.",
    "ja": "更新は、公開されたマニフェストとupdaterメタデータがバンドルされたAux Command署名キーでOpenPGP検証を通過した後にのみインストールします。",
    "pt": "Updates install only after the publied manifest and updater metadados pass OpenPGP verification with the bundled Aux Command signating key.",
    "ru": "Обновления устанавливаются только после того, как опубликованные манифест и метаданные обновителя проходят проверку OpenPGP с помощью пакетного ключа подписи Aux Command.",
    "zh": "更新仅在公布的列表和更新器元数据用捆绑的Aux Command签名密钥通过OpenPGP验证后安装."
  },
