  "Bulk edits preserve credentials. Duplicate matches are suggestions; nothing is merged or deleted automatically. Use / in group names for nested folders.": {
    "en": "Bulk edits preserve credentials. Duplicate matches are suggestions; nothing is merged or deleted automatically. Use / in group names for nested folders.",
    "de": "Sammelbearbeitungen bewahren Anmeldeinformationen. Doppelte Übereinstimmungen sind Vorschläge; nichts wird automatisch zusammengeführt oder gelöscht. Verwenden / in Gruppennamen für verschachtelte Ordner.",
    "es": "Las ediciones a granel preservan las credenciales. Los partidos duplicados son sugerencias; nada se fusiona o elimina automáticamente. Usar / en nombres de grupos para carpetas anidadas.",
    "fr": "Les modifications en vrac conservent les identifiants. Les correspondances dupliquées sont des suggestions; rien n'est fusionné ou supprimé automatiquement. Utilisez / dans les noms de groupe pour les dossiers imbriqués.",
    "it": "Le modifiche Bulk conservano le credenziali. Le partite duplicate sono suggerimenti; nulla viene fuso o eliminato automaticamente.",
    "ja": "一括編集は、認証情報を保存します。重複したマッチは提案です。マージや削除は、自動的にありません。ネストされたフォルダーのグループ名で/使用してください。",
    "pt": "As edições em massa preservam as credenciais. As correspondências duplicadas são sugestões; nada é mesclado ou excluído automaticamente. Use / em nomes de grupos para pastas aninhadas.",
    "ru": "Обширные правки сохраняют учетные данные. Дублирующие совпадения - это предложения; ничто не сливается или не удаляется автоматически. Используйте / в названиях групп для вложенных папок.",
    "zh": "批量编辑保存证书。 复制匹配是建议; 没有自动合并或删除。 在组名中使用 / 用于嵌入式文件夹 。"
  },
