  "Existing authenticated sessions are used. Credentials are not copied into task templates. Output stays in this session; terminal logging, if enabled separately, still applies.": {
    "en": "Existing authenticated sessions are used. Credentials are not copied into task templates. Output stays in this session; terminal logging, if enabled separately, still applies.",
    "de": "Bestehende authentifizierte Sitzungen werden verwendet. Anmeldeinformationen werden nicht in Aufgabenvorlagen kopiert. Die Ausgabe bleibt in dieser Sitzung erhalten; die Protokollierung des Terminals gilt weiterhin, wenn sie separat aktiviert ist.",
    "es": "Se utilizan las sesiones autenticadas existentes. Las credenciales no se copian en plantillas de tareas. La salida se mantiene en esta sesión; la logging terminal, si está habilitada por separado, sigue vigente.",
    "fr": "Des sessions authentifiées existantes sont utilisées. Les lettres de créances ne sont pas copiées dans des modèles de tâches. La sortie reste dans cette session; le logage des terminaux, s'il est activé séparément, s'applique toujours.",
    "it": "Le credenziali non vengono copiate nei modelli di attività. I soggiorni di uscita in questa sessione; la registrazione dei terminali, se abilitata separatamente, si applica ancora.",
    "ja": "認証されたセッションの既存のセッションが使用されます。 クレデンシャルはタスクテンプレートにコピーされていません。 出力は、このセッションにとどまります。 ターミナルロギングは、別々に有効にされている場合は、まだ適用されます。",
    "pt": "São usadas sessões autenticadas existentes. As credenciais não são copiadas para modelos de tarefas. O resultado permanece nesta sessão; o registro do terminal, se ativado separadamente, ainda se aplica.",
    "ru": "Используются существующие аутентифицированные сессии. Удостоверения не копируются в шаблоны задач. Выход остается в этой сессии; регистрация терминала, если она включена отдельно, все еще применяется.",
    "zh": "使用现有的认证会话。 证书不复制到任务模板。 输出会话中会保留; 如果单独启用, 终端记录仍然适用 。"
  },
