    "pt": "Um array JSON ou um objeto com um array profiles. A sincronização partilha nomes de ligação, anfitriões, portas, utilizadores, grupos e etiquetas; comandos de arranque, chaves, anfitriões de salto e reencaminhamentos ficam como definidos neste computador.",
    "ru": "JSON-массив или объект с массивом profiles. Синхронизируются имена подключений, хосты, порты, пользователи, группы и теги; команды запуска, ключи, промежуточные хосты и переадресация остаются как на этом компьютере.",
    "zh": "JSON 数组，或包含 profiles 数组的对象。同步共享连接名称、主机、端口、用户、分组和标签；启动命令、密钥、跳板主机和转发保持本机的设置。"
